-- Public buckets can serve object URLs without a broad storage.objects SELECT policy.
-- Removing this policy prevents clients from listing all files in the media bucket.

drop policy if exists "Public can read blizhniy media" on storage.objects;

-- Keep the media bucket public for object URLs, but do not expose broad storage.objects listing.

update storage.buckets
set
  public = true,
  file_size_limit = 10485760,
  allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp', 'image/gif']
where id = 'blizhniy-media';

drop policy if exists "Public can read blizhniy media" on storage.objects;

-- Move SECURITY DEFINER role helpers out of the exposed public schema.
-- Rewrites all RLS policies that depended on public.is_admin() to private.is_admin().

create schema if not exists private;
revoke all on schema private from public;
revoke all on schema private from anon;
revoke all on schema private from authenticated;

create or replace function private.has_role(required_role public.app_role)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.user_roles
    where user_id = (select auth.uid())
      and role = required_role
  );
$$;

